#!/usr/bin/env python3
"""Standalone control-flow check for the patched good_sigevent().

Runs with cwd = a clean target checkout that already has generated.patch applied.
Extracts the actual good_sigevent() function from kernel/posix-timers.c, compiles it
against minimal stubs with gcc-10, and asserts:
  * the four legal notify modes are accepted (positive paths),
  * invalid notify modes and invalid signal numbers/thread ids are rejected
    (vulnerability-triggering negative paths),
  * the pre-fix implementation accepted the CVE-2017-18344 trigger values,
  * removing the SIGEV_THREAD_ID mask from the SIGEV_NONE comparisons is
    behaviour-preserving over the legal notify-mode domain enforced by the fix.

This is NOT the kernel build; it is a reduced control-flow harness.
"""
import re
import subprocess
import sys
import tempfile
from pathlib import Path

SRC = Path("kernel/posix-timers.c")
CC = "/usr/bin/gcc-10"


def extract_function(text: str, signature_start: str) -> str:
    start = text.index(signature_start)
    brace = text.index("{", start)
    depth = 0
    for i in range(brace, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                return text[start : i + 1]
    raise RuntimeError("unterminated function")


def main() -> int:
    if not SRC.is_file():
        print("FAIL: kernel/posix-timers.c not found in cwd", file=sys.stderr)
        return 2
    text = SRC.read_text(encoding="utf-8", errors="replace")
    new_func = extract_function(text, "static struct pid *good_sigevent(sigevent_t * event)")

    prelude = r"""
#include <stdio.h>
#include <stdlib.h>

#define SIGEV_SIGNAL 0
#define SIGEV_NONE 1
#define SIGEV_THREAD 2
#define SIGEV_THREAD_ID 4
#define SIGRTMAX 64

typedef struct {
	int sigev_notify;
	int sigev_signo;
	int sigev_notify_thread_id;
} sigevent_t;

struct task_struct;
struct pid { int nr; };
struct task_struct {
	struct task_struct *group_leader;
	int tid;
};

static struct task_struct leader_task, other_task, me_task;
static struct pid pid_ok = { 100 };
static struct task_struct *current = &me_task;

static struct task_struct *find_task_by_vpid(int nr)
{
	if (nr == me_task.tid)
		return &me_task;
	return NULL;
}

static int same_thread_group(struct task_struct *a, struct task_struct *b)
{
	return a && b && a->group_leader == b->group_leader;
}

static struct pid *task_pid(struct task_struct *t)
{
	return t ? &pid_ok : NULL;
}

/* Pre-fix reference/target implementation, for the vulnerable-path demonstration. */
static struct pid *good_sigevent_old(sigevent_t * event)
{
	struct task_struct *rtn = current->group_leader;

	if ((event->sigev_notify & SIGEV_THREAD_ID ) &&
		(!(rtn = find_task_by_vpid(event->sigev_notify_thread_id)) ||
		 !same_thread_group(rtn, current) ||
		 (event->sigev_notify & ~SIGEV_THREAD_ID) != SIGEV_SIGNAL))
		return NULL;

	if (((event->sigev_notify & ~SIGEV_THREAD_ID) != SIGEV_NONE) &&
	    ((event->sigev_signo <= 0) || (event->sigev_signo > SIGRTMAX)))
		return NULL;

	return task_pid(rtn);
}

static int failures;

static void expect(const char *what, int got, int want)
{
	if (got != want) {
		printf("FAIL: %s: got %d want %d\n", what, got, want);
		failures++;
	} else {
		printf("ok:   %s: %d\n", what, got);
	}
}
"""

    tests = r"""
int main(void)
{
	sigevent_t ev;
	int legal[] = { SIGEV_SIGNAL, SIGEV_NONE, SIGEV_THREAD,
			SIGEV_SIGNAL | SIGEV_THREAD_ID };
	int bad[] = { 3, 5, 6, 7, 0x100, 255, -1, 1000 };
	unsigned i;

	leader_task.group_leader = &leader_task;
	leader_task.tid = 50;
	other_task.group_leader = &other_task;
	other_task.tid = 60;
	me_task.group_leader = &leader_task;
	me_task.tid = 100;

	/* positive paths: legal notify modes must be accepted by the fixed code */
	ev.sigev_signo = 14; ev.sigev_notify_thread_id = 0;
	ev.sigev_notify = SIGEV_SIGNAL;
	expect("fixed SIGEV_SIGNAL", good_sigevent(&ev) != NULL, 1);
	ev.sigev_notify = SIGEV_NONE; ev.sigev_signo = 0;
	expect("fixed SIGEV_NONE", good_sigevent(&ev) != NULL, 1);
	ev.sigev_notify = SIGEV_THREAD; ev.sigev_signo = 14;
	expect("fixed SIGEV_THREAD", good_sigevent(&ev) != NULL, 1);
	ev.sigev_notify = SIGEV_SIGNAL | SIGEV_THREAD_ID;
	ev.sigev_signo = 14; ev.sigev_notify_thread_id = 100;
	expect("fixed SIGEV_SIGNAL|THREAD_ID own tid", good_sigevent(&ev) != NULL, 1);

	/* negative paths */
	ev.sigev_notify = SIGEV_SIGNAL | SIGEV_THREAD_ID;
	ev.sigev_signo = 14; ev.sigev_notify_thread_id = 999;
	expect("fixed THREAD_ID unknown tid rejected", good_sigevent(&ev) == NULL, 1);
	ev.sigev_notify = SIGEV_SIGNAL | SIGEV_THREAD_ID;
	ev.sigev_signo = 14; ev.sigev_notify_thread_id = 60; /* other thread group */
	expect("fixed THREAD_ID other group rejected", good_sigevent(&ev) == NULL, 1);
	ev.sigev_notify = SIGEV_SIGNAL; ev.sigev_signo = 0;
	expect("fixed signo 0 rejected", good_sigevent(&ev) == NULL, 1);
	ev.sigev_notify = SIGEV_SIGNAL; ev.sigev_signo = 65;
	expect("fixed signo > SIGRTMAX rejected", good_sigevent(&ev) == NULL, 1);
	ev.sigev_notify = SIGEV_THREAD; ev.sigev_signo = -1;
	expect("fixed signo -1 rejected", good_sigevent(&ev) == NULL, 1);
	ev.sigev_notify = SIGEV_SIGNAL | SIGEV_THREAD_ID;
	ev.sigev_signo = 0; ev.sigev_notify_thread_id = 100;
	expect("fixed THREAD_ID signo 0 rejected", good_sigevent(&ev) == NULL, 1);

	for (i = 0; i < sizeof(bad) / sizeof(bad[0]); i++) {
		char buf[64];
		ev.sigev_notify = bad[i];
		ev.sigev_signo = 14;
		ev.sigev_notify_thread_id = 0;
		snprintf(buf, sizeof(buf), "fixed invalid notify 0x%x rejected", bad[i]);
		expect(buf, good_sigevent(&ev) == NULL, 1);
	}

	/* pre-fix code accepted the 0x100 trigger value: CVE-2017-18344 root cause */
	ev.sigev_notify = 0x100; ev.sigev_signo = 14; ev.sigev_notify_thread_id = 0;
	expect("pre-fix accepted 0x100 (vulnerable)", good_sigevent_old(&ev) != NULL, 1);
	ev.sigev_notify = 5; ev.sigev_signo = 14;
	expect("pre-fix accepted 5 (vulnerable)", good_sigevent_old(&ev) != NULL, 1);

	/* mask removal is behaviour-preserving on the legal notify-mode domain */
	for (i = 0; i < sizeof(legal) / sizeof(legal[0]); i++) {
		char buf[64];
		int v = legal[i];
		int old = ((v & ~SIGEV_THREAD_ID) == SIGEV_NONE);
		int new = (v == SIGEV_NONE);
		snprintf(buf, sizeof(buf), "mask-equivalence notify %d", v);
		expect(buf, old == new, 1);
	}

	if (failures) {
		printf("RESULT: %d failure(s)\n", failures);
		return 1;
	}
	printf("RESULT: all good_sigevent control-flow assertions passed\n");
	return 0;
}
"""

    with tempfile.TemporaryDirectory(prefix="good-sigevent-check-") as td:
        c_file = Path(td) / "check.c"
        exe = Path(td) / "check"
        c_file.write_text(prelude + "\n" + new_func + "\n" + tests, encoding="utf-8")
        comp = subprocess.run([CC, "-O0", "-Wall", "-o", str(exe), str(c_file)],
                              capture_output=True, text=True)
        sys.stdout.write(comp.stdout)
        sys.stderr.write(comp.stderr)
        if comp.returncode != 0:
            print("FAIL: compilation failed")
            return 1
        run = subprocess.run([str(exe)], capture_output=True, text=True)
        sys.stdout.write(run.stdout)
        sys.stderr.write(run.stderr)
        return run.returncode


if __name__ == "__main__":
    raise SystemExit(main())

